function botsebitaGetLanguage() {
  try {
    const saved = localStorage.getItem('botsebita-lab-tv-language');
    return BOTSEBITA_LANGUAGES.some(item => item.code === saved) ? saved : 'es';
  } catch (_) { return 'es'; }
}

let botsebitaLanguage = botsebitaGetLanguage();
function botsebitaT(key, vars = {}) {
  const languagePack = BOTSEBITA_I18N[botsebitaLanguage] || BOTSEBITA_I18N.es;
  let value = languagePack[key] || BOTSEBITA_I18N.en[key] || BOTSEBITA_I18N.es[key] || key;
  return String(value).replace(/\{\{(\w+)\}\}/g, (_match, name) => String(vars[name] ?? ''));
}

function botsebitaApplyLanguage(language) {
  if (!BOTSEBITA_LANGUAGES.some(item => item.code === language)) language = 'es';
  botsebitaLanguage = language;
  const languageMeta = BOTSEBITA_LANGUAGES.find(item => item.code === language);
  document.documentElement.lang = language;
  document.documentElement.dir = languageMeta?.dir || 'ltr';
  try { localStorage.setItem('botsebita-lab-tv-language', language); } catch (_) {}

  document.querySelectorAll('[data-i18n]').forEach(element => {
    element.textContent = botsebitaT(element.dataset.i18n);
  });
  document.querySelectorAll('[data-i18n-html]').forEach(element => {
    element.innerHTML = botsebitaT(element.dataset.i18nHtml);
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(element => {
    element.placeholder = botsebitaT(element.dataset.i18nPlaceholder);
  });
  document.querySelectorAll('[data-i18n-title]').forEach(element => {
    element.title = botsebitaT(element.dataset.i18nTitle);
  });
  document.querySelectorAll('[data-i18n-aria]').forEach(element => {
    element.setAttribute('aria-label', botsebitaT(element.dataset.i18nAria));
  });
  const select = document.getElementById('languageSelect');
  if (select) select.value = language;
}

window.BOTSEBITA_LANGUAGES = BOTSEBITA_LANGUAGES;
window.botsebitaT = botsebitaT;
window.botsebitaApplyLanguage = botsebitaApplyLanguage;

